439:         public ExcuteResult TransferAutoLoaderToLoading(bool isManual = false)
440:         {
441:             try
442:             {
443:                 // 检查loading段有没有板
444:                 if (this.TransportProgram.LoadingSubSectionProgram.SubSectionState == SubSectionStateEnum.NoMaterial)
445:                 {
446:                 Retry:
447: 
448:                     // 没有的话就给送板机发信号
449:                     this.LoadingSubSectionController.SetLoadingTableNeedTabletSignal(true);
450: 
451:                     Stopwatch sp = Stopwatch.StartNew();
452: 
453:                     while (true)
454:                     {
455:                         // 送板机是否传料成功
456:                         bool hasMaterial = this.LoadingSubSectionController.HasMaterialOnFront();
457: 
458:                         if (hasMaterial)
459:                         {
460:                             // 同时皮带传送
461:                             this.TransportProgram.LoadingSubSectionProgram.SubSectionTransferState =
462:                                 SubSectionStateTransferEnum.Transfering;
463: 
464:                             // 皮带1转动
465:                             this.LoadingSubSectionController.MoveBeltNoWaitArrive();
466: 
467:                             Thread.Sleep(200);
468: 
469:                             // 关要料信号
470:                             this.LoadingSubSectionController.SetLoadingTableNeedTabletSignal(false);
471: 
472:                             Thread.Sleep(500);
473: 
474:                             // 皮带停止
475:                             this.LoadingSubSectionController.StopMove();
476: 
477:                             break;
478:                         }
479: 
480:                         // 超时报警,暂定5s
481:                         if (sp.ElapsedMilliseconds > 5000)
482:                         {
483:                             this.TransportProgram.LoadingSubSectionProgram.SubSectionTransferState =
484:                                 SubSectionStateTransferEnum.Alarm;
485: 
486:                             // 关要料信号,防止换料时板子一直流
487:                             this.LoadingSubSectionController.SetLoadingTableNeedTabletSignal(false);
488: 
489:                             DialogResult dr = AKRSMessageBoxExt.Show(
490:                                 @"上料超时!",
491:                                 $"报警",
492:                                 new[] { "重试", "终止", "不再上料" },
493:                                 new[] { DialogResult.Retry, DialogResult.Abort, DialogResult.Ignore });
494: 
495:                             switch (dr)
496:                             {
497:                                 case DialogResult.Retry:
498:                                     goto Retry;
499: 
500:                                 case DialogResult.Abort:
501:                                     // 停止
502:                                     return ExcuteResult.Abort;
503: 
504:                                 // 不再上料
505:                                 case DialogResult.Ignore:
506: 
507:                                     TransportProvider.ContinuousFeeding = false;
508: 
509:                                     return ExcuteResult.NoStart;
510:                             }
511:                         }
512: 
513:                         Thread.Sleep(1);
514:                     }
515:                 }
516:                 else
517:                 {
518:                     // 有的话不发信号
519:                     this.LoadingSubSectionController.SetLoadingTableNeedTabletSignal(false);
520: 
521:                     return ExcuteResult.NoStart;
522:                 }
523: 
524:                 // 状态改成有料
525:                 this.TransportProgram.LoadingSubSectionProgram.SubSectionState =
526:                     SubSectionStateEnum.HasMaterial;
527:                 this.TransportProgram.LoadingSubSectionProgram.TransportUnit = new TransportUnit(CurrentMachineSystemEnum.System2);
528: 
529:                 this.TransportProgram.Save();
530:                 return ExcuteResult.Success;
531:             }
532:             catch (Exception ex)
533:             {
534:                 LogHelper.Post(
535:                     Level.Error,
536:                     $"产品从送板机传到上料载台出现异常",
537:                     ex,
538:                     LogCategory.Transport);
539: 
540:                 AKRSXtraMessageBox.Show(
541:                     $@"产品从送板机传到上料载台出现异常: \r\n
542:                                           Exception message:{ex.Message} \r\n
543:                                           StackTrace: {ex.StackTrace}",
544:                     "异常",
545:                     MessageBoxButtons.OK,
546:                     MessageBoxIcon.Error);
547: 
548:                 return ExcuteResult.Exception;
549:             }
550:         }

