189:         /// </summary>
190:         private void ReDispense()
191:         {
192:             // 焊点
193:             BondPosition bp = System1Domain.GetInstance().ActionNodeController.CurrentBondPosition;
194:             
195:             // 重置前面的动作节点,重新取贴
196:             List<ActionNode> actionNodeList = new List<ActionNode>
197:                                                   {
198:                                                       System1Domain.GetInstance().DispenseActionNodes.S1DispenseActionNode,
199:                                                       System1Domain.GetInstance().DispenseActionNodes.S1DispenseDefectActionNode,
200:                                                   };
201:             
202:             // 将所有的都变成没有完成，后面后修改
203:             foreach (var key in bp.BondPositionInfo.S1RemainingSteps.Keys)
204:             {
205:                 bp.BondPositionInfo.S1RemainingSteps[key] = false;
206:                 DispenseRunTimeProvider.RecordTime("系统1胶量检测", $"补胶将步骤{key}改为未完成");
207:             }
208: 
209:             System1Domain.GetInstance().ActionNodeController.SetActionNodeReWork(actionNodeList);
