212:         /// <summary>
213:         /// 检测结果处理
214:         /// </summary>
215:         /// <param name="baseAlgResults">检测结果</param>
216:         /// <returns>结果</returns>
217:         /// <exception cref="Exception">未知异常</exception>
218:         private ExcuteResult EpoxyApplicationDefect(List<BaseAlgResult> baseAlgResults)
219:         {
220:             ExcuteResult excuteResult = this.PostBondInspection.PostBondEpoxyCheck(baseAlgResults, BondPosition, System1Domain.GetInstance().DispenseVisionController.GetHardware());
221: 
222:             DispenseRunTimeProvider.RecordTime("系统1胶量检测", $"胶量检测处理结果为{excuteResult}");
223: 
224:             if (excuteResult == ExcuteResult.Success)
225:             {
226:                 BondPosition.S1FinishedStep(this.ActionNodeController.SingleProcessStepName);
227:                 return ExcuteResult.Success;
228:             }
229:             else if (excuteResult == ExcuteResult.Fail)
230:             {
231:                 BondPosition.SetMatterDisable();
232:                 return ExcuteResult.Success;
233:             }
234:             else if (excuteResult == ExcuteResult.Abort)
235:             {
236:                 Machine.GetInstance().Stop();
237:                 return ExcuteResult.Abort;
238:             }
239:             else if (excuteResult == ExcuteResult.Retry)
240:             {
241:                 this.ReDispense();
242:                 return ExcuteResult.Retry;
243:             }
244:             else
245:             {
246:                 throw new Exception("胶量检测未知错误");
247:             }
248:         }

