199:         /// <summary>
200:         /// 系统1定位
201:         /// </summary>
202:         /// <param name="baseEntity">实体对象</param>
203:         /// <param name="type">定位类型</param>
204:         /// <returns>结果</returns>
205:         private bool System1VisionByPos(BaseMatter baseEntity, TuService.NormalVisionType type,bool alarm = false)
206:         {
207:             // 单步工作
208:             if (!System1Domain.GetInstance().WaitSingleStep())
209:             {
210:                 return false;
211:             }
212: 
213:             LogHelper.Post(Level.Info, $"点胶{type}定位开始", LogCategory.Dispense);
214: 
215:             #region 先决条件判断
216: 
217:             //if (MachineStateModel.GetInstance().MachineState == MachineStateEnum.Stop)
218:             //{
219:             //    return false;
220:             //}
221: 
222:             if (baseEntity.EntityState == EntityState.Fail)
223:             {
224:                 return false;
225:             }
226: 
227:             #endregion
228: 
229:             // 根据信息获取坐标
230:             (AKRSPoint3D point, string pRName, bool autofocus) = TuService.GetVisionInfo(baseEntity, type);
231: 
232:             // 转换到G0坐标上面去
233:             AKRSPoint3D p1VisionPosInG01 =
234:                 baseEntity.CoordinateSystem.SelfPosToG0(point);
235: 
236:             // 添加差值
237:             p1VisionPosInG01 = this.DispenseController.GetG0VisionPos(p1VisionPosInG01);
238: 
239:             MatchResult matchResult1 = null;
240: 
241:             if (!alarm)
242:             {
243:                 matchResult1 = (MatchResult)this.DispenseVisionController.DispenseVision(p1VisionPosInG01, pRName,autofocus);
244: 
245:                 #region 四周定位
246: 
247:                 if (baseEntity.Config.LocateConfig.IsAroundLocate && matchResult1 == null)
248:                 {
249:                     for (int i = 0; i < 4; i++)
250:                     {
251:                         if (i == 0)
252:                         {
253:                             // 执行定位
254:                             matchResult1 = (MatchResult)this.DispenseVisionController.DispenseVision(
255:                                 new AKRSPoint3D(
256:                                     p1VisionPosInG01.X + baseEntity.Config.LocateConfig.AroundLocateDistance,
257:                                     p1VisionPosInG01.Y,
258:                                     p1VisionPosInG01.Z),
259:                                 pRName);
260: 
261:                             if (matchResult1 != null)
262:                             {
263:                                 break;
264:                             }
265:                         }
266:                         else if (i == 1)
267:                         {
268:                             // 执行定位
269:                             matchResult1 = (MatchResult)this.DispenseVisionController.DispenseVision(
270:                                 new AKRSPoint3D(p1VisionPosInG01.X - baseEntity.Config.LocateConfig.AroundLocateDistance, p1VisionPosInG01.Y, p1VisionPosInG01.Z),
271:                                 pRName);
272: 
273:                             if (matchResult1 != null)
274:                             {
275:                                 break;
276:                             }
277:                         }
278:                         else if (i == 2)
279:                         {
280:                             // 执行定位
281:                             matchResult1 = (MatchResult)this.DispenseVisionController.DispenseVision(
282:                                 new AKRSPoint3D(
283:                                     p1VisionPosInG01.X,
284:                                     p1VisionPosInG01.Y + baseEntity.Config.LocateConfig.AroundLocateDistance,
285:                                     p1VisionPosInG01.Z),
286:                                 pRName);
287: 
288:                             if (matchResult1 != null)
289:                             {
290:                                 break;
291:                             }
292:                         }
293:                         else if (i == 3)
294:                         {
295:                             // 执行定位
296:                             matchResult1 = (MatchResult)this.DispenseVisionController.DispenseVision(
297:                                 new AKRSPoint3D(
298:                                     p1VisionPosInG01.X,
299:                                     p1VisionPosInG01.Y - baseEntity.Config.LocateConfig.AroundLocateDistance,
300:                                     p1VisionPosInG01.Z),
301:                                 pRName);
302: 
303:                             if (matchResult1 != null)
304:                             {
305:                                 break;
306:                             }
307:                         }
308:                     }
309:                 }
310: 
311:                 #endregion
312:             }
313:             
314:             // 结果判断
315:             if (matchResult1 == null)
316:             {
317:                 this.DispenseController.MoveToG0Pos3D(p1VisionPosInG01);
318: 
319:                 PREntity pREntityTemp = (PREntity)VisionEntityRepository.GetInstance().Find(pRName);
320:                 // PREntity pREntity = DispenseRunTimeProvider.GetDispensePREntity(pREntityTemp);
321: 
322:                 (DialogResult dialogResult, BaseAlgResult match) result = UcMainSystem.VisionAlarmLockFunc(pREntityTemp, baseEntity.Name, $"{baseEntity.MatterTypeEnum}点胶定位失败", this.DispenseVisionController.GetHardware());
323:                 if (result.dialogResult == DialogResult.OK)
324:                 {
325:                     matchResult1 = (MatchResult)result.match;
326:                 }
327:                 else if (result.dialogResult == DialogResult.Ignore)
328:                 {
329:                     baseEntity.SetMatterDisable();
330:                     return false;
331:                 }
332:                 else if (result.dialogResult == DialogResult.Abort)
333:                 {
334:                     Machine.GetInstance().Stop();
335:                     return false;
336:                 }
337:                 else
338:                 {
339:                     return false;
340:                 }
341:             }
342: 
343:             #region 信息保存
344: 
345:             // 定位结果转换
346:             AKRSPoint3D realPoint3DInG0 = this.DispenseController.ConvertVisionResultInG0(matchResult1);
347: 
348:             // 转到G0
349:             realPoint3DInG0 = this.DispenseController.GetG0PosFromVision(realPoint3DInG0);
350: 
351:             // 转到自己的坐标系
352:             AKRSPoint3D realPoint3D = baseEntity.CoordinateSystem.G0PosToSelf(realPoint3DInG0);
353: 
354:             VisionResult visionResult = TuService.ChooseInfoByType(type, baseEntity);
355: 
356:             visionResult.SaveInfo(matchResult1, realPoint3D, realPoint3DInG0, this.DispenseController.GetG0Pos());
357: 
358:             LogHelper.Post(Level.Info, $"点胶{type}定位结束", LogCategory.Dispense);
359: 
360:             return true;
361:             #endregion

