s1-update-coordinate.code:
553:         public static void UpdateEntity(BaseMatter baseEntity, NormalVisionType type)
554:         {
555:             baseEntity.BaseInfo.LocateResultInfo.P1Info.Bitmap = null;
556:             baseEntity.BaseInfo.LocateResultInfo.P2Info.Bitmap = null;
557:             baseEntity.BaseInfo.LocateResultInfo.P3Info.Bitmap = null;
558:             baseEntity.BaseInfo.LocateResultInfo.P4Info.Bitmap = null;
559: 
560:             // 根据定位的配置计算出原始点位和现在的点位
561:             AKRSPoint3D oldPoint = CalculateOldPoint(baseEntity.Config.LocateConfig);
562:             AKRSPoint3D newPoint = CalculateNewPoint(baseEntity.BaseInfo.LocateResultInfo, baseEntity.Config.LocateConfig);
563: 
564: 
565:             // 海康的坐标系是顺时针的，所有需要加负号
566:             double newDegree = -CalculateUpdateAngle(
567:                 baseEntity.BaseInfo.LocateResultInfo,
568:                 baseEntity.Config.LocateConfig);
569: 
570:             double oldDegree = baseEntity.CoordinateSystem.Degree;
571: 
572:             // 上层坐标系现在的角度
573:             GeneralCoordinateSystem upperSystem = (GeneralCoordinateSystem)baseEntity.CoordinateSystem.UpperCoordinateSystem;
574:             double upperSystemAngle = upperSystem.DegreeInG0();
575: 
576:             // 更新的角度为：视觉定位的角度 - 示教时的角度 - 上层的角度
577:             double updateDegree = newDegree - upperSystemAngle - 0;
578: 
579:             if (baseEntity.Config.LocateConfig.IsCalculateAngleByTwoPoint && baseEntity.Config.LocateConfig.AdjustType >= AdjustTypeEnum.TwoPoints)
580:             {
581:                 double oldAngle = Math.Atan2(
582:                     baseEntity.Config.LocateConfig.P2VisionRelativePos.Y - baseEntity.Config.LocateConfig.P1VisionRelativePos.Y,
583:                     baseEntity.Config.LocateConfig.P2VisionRelativePos.X - baseEntity.Config.LocateConfig.P1VisionRelativePos.X);
584: 
585:                 double newAngle = Math.Atan2(
586:                     baseEntity.BaseInfo.LocateResultInfo.P2Info.ResultPoint3D.Y - baseEntity.BaseInfo.LocateResultInfo.P1Info.ResultPoint3D.Y,
587:                     baseEntity.BaseInfo.LocateResultInfo.P2Info.ResultPoint3D.X - baseEntity.BaseInfo.LocateResultInfo.P1Info.ResultPoint3D.X);
588: 
589:                 updateDegree = Math.Atan(newAngle - oldAngle) - upperSystemAngle - 0;
590:             }
591: 
592:             if (baseEntity.Config.LocateConfig.IsThreePointFittingCircle
593:                 && (baseEntity.Config.LocateConfig.AdjustType == AdjustTypeEnum.ThreePoints || baseEntity.Config.LocateConfig.AdjustType == AdjustTypeEnum.FourPoints))
594:             {
595:                 oldPoint = MathHelper.GetCentre(
596:                     baseEntity.Config.LocateConfig.P1VisionRelativePos,
597:                     baseEntity.Config.LocateConfig.P2VisionRelativePos,
598:                     baseEntity.Config.LocateConfig.P3VisionRelativePos);
599: 
600:                 newPoint = MathHelper.GetCentre(
601:                     baseEntity.BaseInfo.LocateResultInfo.P1Info.ResultPoint3D,
602:                     baseEntity.BaseInfo.LocateResultInfo.P2Info.ResultPoint3D,
603:                     baseEntity.BaseInfo.LocateResultInfo.P3Info.ResultPoint3D);
604:             }
605: 
606:             baseEntity.CoordinateSystem.UpdateCoordinateSystem(oldPoint, newPoint, updateDegree);
607: 
608:             baseEntity.BaseInfo.IsVisioned = true;
609:         }

