195: 
196:             // 获取拍照位
197:             AKRSPoint3D componentVisionPosInG0 = Block.GetInstance().GetResultDieG0Pos();
198:             AKRSPoint3D componentVision3DPos =
199:                 this.bondModuleController.ConvertG0ToMachinePos(componentVisionPosInG0);
200: 
201:             AKRSPoint4D componentVision4DPos = new AKRSPoint4D()
202:             {
203:                 X = componentVision3DPos.X,
204:                 Y = componentVision3DPos.Y,
205:                 Z = componentVision3DPos.Z,
206:                 T = this.nozzle.AlignAngle
207:             };
208: 
209:             if (this.isSkipComponent == false)
210:             {
211:                 // 去静态华夫盒拍照位
212:                 ExcuteResult ret = this.MoveToStaticWaffleVisionPos(componentVision4DPos);
213:                 if (ret != ExcuteResult.Success)
214:                 {
215:                     return (ret, null);
216:                 }
217:             }
218:             else
219:             {
220:                 double curLevel = this.bondHeadController.GetAxisZRealPos();
221: 
222:                 if (Math.Abs(curLevel - componentVision4DPos.Z) < 0.01)
223:                 {
