225:                     this.bondModuleController.MoveBondXY(componentVision3DPos.X, componentVision3DPos.Y);
226:                 }
227:                 else
228:                 {
229:                     this.bondModuleController.MoveSafeBondXYZT(componentVision4DPos);
230:                 }
231:             }
232: 
233:             System2RunTimeProvider.RecordTime("PickActionNode", $"运动到静态华夫盒拍照位完成");
234: 
235:             // Bond定位
236:             MatchResult matchResult = (MatchResult)this.system2Controller.BondCameraVision(
237:                null,
238:                component.DieMatchName);
239: 
240:             System2RunTimeProvider.RecordTime("PickActionNode", $"静态华夫盒拍照位完成");
241: 
242:             // 结果判断
243:             if (matchResult == null)
244:             {
245:                 if (component.BlankDieAutoSkipMaxTimes != 0
246:                     && System2RunTimeProvider.StaticWaffleComponentAutoSkipCount < component.BlankDieAutoSkipMaxTimes)
247:                 {
248:                     // 刷新Map信息
249:                     WaferSystemDomain.GetInstance().Block.RefreshMap();
250: 
251:                     // 芯片名称传给晶圆台
252:                     WaferSystemDomain.GetInstance().WaferSubSystemTask.SetCurrentNeedChipName(component.Name);
253: 
254:                     // 给晶圆台发要料信号
255:                     SignalPool.GetInstance().IsBondNeedChipSignal.Set();
256: 
257:                     System2RunTimeProvider.RecordTime("取片信号交互", $"定位报警，给晶圆发要料信号，芯片名称{component.Name}");
258: 
259:                     this.isSkipComponent = true;
260: 
261:                     // 跳过次数+1
262:                     System2RunTimeProvider.StaticWaffleComponentAutoSkipCount++;
263: 
264:                     return (ExcuteResult.Retry, null);
265:                 }
266: 
267:                 // 跳过次数清零
268:                 System2RunTimeProvider.StaticWaffleComponentAutoSkipCount = 0;
269: 
270:                 PREntity pREntity = (PREntity)VisionEntityRepository.GetInstance().Find(component.DieMatchName);
271: 
272:                 // 报警
273:                 (DialogResult dialog, BaseAlgResult baseAlgResult) result =
274:                     UcMainSystem.VisionAlarmFunc(pREntity, bp.Name, "静态华夫盒拍照失败");
275: 
276:                 if (result.dialog == DialogResult.OK)
277:                 {
278:                     matchResult = (MatchResult)result.baseAlgResult;
279:                 }
280:                 // 跳过
281:                 else if (result.dialog == DialogResult.Ignore)
282:                 {
283:                     // 刷新Map信息
