291: 
292:                     System2RunTimeProvider.RecordTime("取片信号交互", $"定位报警，给晶圆发要料信号，芯片名称{component.Name}");
293: 
294:                     this.isSkipComponent = true;
295: 
296:                     return (ExcuteResult.Retry, null);
297:                 }
298:                 else if (result.dialog == DialogResult.Abort)
299:                 {
300:                     return (ExcuteResult.Abort, null);
301:                 }
302:                 else
303:                 {
304:                     return (ExcuteResult.Abort, null);
