228:                         bool hasMaterial = !this.bondHeadController.ComponentCheckAfterBonding(
229:                         this.bondHeadController.GetCurrentNozzle());
230: 
231:                         // 关闭真空
232:                         Task.Run(this.bondHeadController.CloseToolVaccum);
233: 
234:                         if (hasMaterial)
235:                         {
236:                             DialogResult dialog = AKRSMessageBoxExt.Show(
237:                                 $"真空检测到吸嘴上还有芯片，请检查吸嘴!  \r\n" + "重贴：重新贴片\r\n" + "终止：退出工作\r\n" + "忽略：忽略，抛料后继续工作\r\n" + "重新取贴: 抛料重取\r\n",
238:                                 "报警",
239:                                 new string[] { "重贴", "终止", "忽略", "重新取贴" },
240:                                 new DialogResult[] { DialogResult.Retry, DialogResult.Abort, DialogResult.Ignore, DialogResult.Cancel });
241: 
242:                             switch (dialog)
243:                             {
244:                                 // 重新Bond
245:                                 case DialogResult.Retry:
246: 
247:                                     goto ReBond;
248: 
249:                                 // 终止
250:                                 case DialogResult.Abort:
251: 
252:                                     StatisticsDomain.GetInstance().BondFailedCount++;
253:                                     return ExcuteResult.Abort;
254: 
255:                                 // 忽略
256:                                 case DialogResult.Ignore:
257: 
258:                                     StatisticsDomain.GetInstance().BondFailedCount++;
259:                                     this.bondModuleController.ThrowAction();
260:                                     break;
261: 
262:                                 // 取消
263:                                 case DialogResult.Cancel:
264: 
265:                                     StatisticsDomain.GetInstance().BondFailedCount++;
266: 
267:                                     this.bondModuleController.ThrowAction();
268: 
269:                                     // 抛掉的芯片+1
270:                                     component.AddCountOfReject();
271: 
272:                                     // 重置前面的动作节点,重新取贴
273:                                     List<ActionNode> actionNodeList = new List<ActionNode>();
274:                                     actionNodeList.Add(this.system2Domain.BondActionNodeRepository.PickActionNode);
275:                                     if (component.AccuracyMode != AccuracyModeEnum.Off
276:                     && component.AdjustCamera == CameraTypeEnum.UpLookCamera)
277:                                     {
278:                                         actionNodeList.Add(this.system2Domain.BondActionNodeRepository.UpLookCorrectionActionNode);
279:                                     }
280: 
281:                                     if (component.AccuracyMode != AccuracyModeEnum.Off
282:                    && component.AdjustCamera == CameraTypeEnum.BondCamera)
283:                                     {
284:                                         actionNodeList.Add(this.system2Domain.BondActionNodeRepository.SubstrateCameraCorrectionActionNode);
285:                                     }
286: 
287:                                     actionNodeList.Add(this.system2Domain.BondActionNodeRepository.BondActionNode);
288:                                     this.system2Domain.ActionNodesService.SetActionNodeReWork(actionNodeList);
289: 
290:                                     System2RunTimeProvider.IsRepickComponent = true;
291: 
292:                                     return ExcuteResult.Retry;
293:                             }
294:                         }
295: 
296:                         System2RunTimeProvider.RecordTime("BondAction", $"焊后回带检测完成");
297:                     }
298:                 }
299: 
300:             #endregion
301: 
302:                 #region 隔几颗去看一下胶印
303: 
304:                 if (component.IsDipOnTU
305:                     && System2RunTimeProvider.WatchFluxCount % component.DipOnTUAfterBondingNum == 0)
306:                 {
307:                     System2RunTimeProvider.WatchFluxCount = 0;
308: 
309:                     // 去看胶印
310:                     ExcuteResult ret = this.DipFluxOnBondPositionVision(component, bondPos);
311: 
312:                     switch (ret)
313:                     {
314:                         case ExcuteResult.Success:
315:                             break;
316: 
317:                         case ExcuteResult.Fail:
318:                             StatisticsDomain.GetInstance().BondFailedCount++;
319:                             break;
320: 
321:                         case ExcuteResult.Abort:
322:                             return ExcuteResult.Abort;
323: 
324:                         case ExcuteResult.Exception:
325:                             StatisticsDomain.GetInstance().BondFailedCount++;
326:                             DialogResult dialog = AKRSMessageBoxExt.Show(
327:                                 $" Bond相机识别PR:{component.DipPRName}异常，设备将退出自动工作！",
328:                                 "报警",
329:                                 new string[] { "确认" },
330:                                 new DialogResult[] { DialogResult.OK });
331: 
332:                             return ExcuteResult.Exception;
333:                     }
334:                 }
335: 
336:                 System2RunTimeProvider.WatchFluxCount++;
337: 
338:                 #endregion
339: 
340:                 // 按快捷键 去看已经贴完的BondPosition
341:                 this.VisionPreviousBondPosition();
342: 
343:                 SkipBond:
344: 
345:                 System2RunTimeProvider.IsMaterialOnBondhead = false;
346: 
347:                 // 修改制程
348:                 this.bondPosition.S2FinishedStep(this.actionNodesService.GetCurrentProcessStepName());
349: 
350:                 // 统计固精周期，异步，如果出现卡顿，屏蔽掉
351:                 StatisticsDomain.GetInstance().StatisticsBondPositionInfo(this.bondPosition,this.component);
352: 
353:                 System2RunTimeProvider.RecordTime("BondAction", "统计固精周期 完成");
354: 
355:                 this.bondHeadController.GetCurrentNozzle().FrequencyConsumables.CurrentUseTimes++;
356: 
357:                 // 检查贴片颗数是否超上限 
358:                 this.CheckBondedNumber();
359: 
360:                 UcMainSystem.ReFreshSystem2TuAction();
361: 
362:                 System2RunTimeProvider.RecordTime("BondAction", "Action 结束");
363: 
364:                 return ExcuteResult.Success;
365:             }
366:             catch (Exception ex)
367:             {
368:                 LogHelper.Post(Level.Error, $"流程{this.Name}运行故障", ex, LogCategory.Bond);
369:                 AKRSMessageBoxExt.Show(ex.Message, "Exception", new string[] { "Exception" }, new DialogResult[] { DialogResult.Yes });
370:                 return ExcuteResult.Exception;
371:             }
372:             finally
373:             {
374:                 this.State = RunStateEnum.Stop;
375:                 this.WorkStop?.Invoke();
376:             }
377:         }

