462:         /// <summary>
463:         /// 贴片
464:         /// </summary>
465:         /// <param name="bondType">贴片类型</param>
466:         /// <returns>结果</returns>
467:         private ExcuteResult Bond(BondTypeEnum bondType)
468:         {
469:             System2RunTimeProvider.RecordTime("Bond", "Bond  开始");
470: 
471:             try
472:             {
473:                 BondActionParameter bondActionParameter =
474:                     this.bondActionProvider.GetBondActionParameter(component, bondType);
475: 
476:                 // 预备抬起位
477:                 double liftPreLevel = this.bondLevel + bondActionParameter.SlowTravelDistanceAfterPlace;
478: 
479:                 // 二段速去固精高度
480:                 this.SlowDownToBondLevel(bondActionParameter);
481: 
482:                 System2RunTimeProvider.RecordTime("Bond", "低速移动到固晶高度完成");
483: 
484:                 int placementDelay = (bondActionParameter.PlacementDelay - bondActionParameter.VacuumOffDelay) > 0
485:                             ? (bondActionParameter.PlacementDelay - bondActionParameter.VacuumOffDelay)
486:                             : 0;
487: 
488:                 // 固晶延迟
489:                 DelayHelper.Delay(placementDelay);
490: 
491:                 System2RunTimeProvider.RecordTime("Bond", $"固精延时: {bondActionParameter.PlacementDelay}ms");
492: 
493:                 // 蘸胶不关真空也不弱吹
494:                 if (bondType != BondTypeEnum.DipFluxOnTU)
495:                 {
496:                     // 关闭吸嘴真空
497:                     this.bondHeadController.CloseToolVaccum();
498: 
499:                     System2RunTimeProvider.RecordTime("Bond", $"关吸嘴真空");
500: 
501:                     // 异步开弱吹
502:                     this.BlowAsyn(bondActionParameter);
503: 
504:                     // 关真空延迟
505:                     DelayHelper.Delay(bondActionParameter.VacuumOffDelay);
506: 
507:                     System2RunTimeProvider.RecordTime("Bond", $" 关真空延时: {bondActionParameter.VacuumOffDelay}ms");
508:                 }
509: 
510:                 // 记录最终贴片力
511:                 this.RecordLastBondForce();
512: 
513:                 // 结束力控读取
514:                 UcMainSystem.ActiveReadBondForce(false);
515: 
516:                 // 二段速低速上抬
517:                 this.SlowUpToLiftLevel(liftPreLevel, bondActionParameter);
518: 
519:                 System2RunTimeProvider.RecordTime("Bond", $"Bond  完成");
520:             }
521:             catch (Exception ex)
522:             {
523:                 LogHelper.Post(Level.Error, $"固晶失败", ex, LogCategory.Bond);
524: 
525:                 DialogResult dialogResult = AKRSMessageBoxExt.Show(
526:                     $"固晶失败! \r\n" + ex.ToString(),
527:                     "固晶报警",
528:                     new string[] { "确认" },
529:                     new DialogResult[] { DialogResult.OK },
530:                     AlarmLevel.SecondLevel);
531: 
532:                 return ExcuteResult.Exception;
533:             }
534: 
535:             return ExcuteResult.Success;
536:         }
