76:         /// <param name="bondPos">贴片位</param>
77:         /// <returns>结果</returns>
78:         private ExcuteResult DipFluxOnBondPositionVision(BaseCarrierConfig component, AKRSPoint4D bondPos)
79:         {
80:             System2RunTimeProvider.RecordTime("Bond", "准备去看焊点的蘸胶印子");
81: 
82:             if (MachineHardwareConfiguration.GetInstance().IsSlideFluxerConfigured == false)
83:             {
84:                 throw new Exception("未配置刮胶盘硬件！");
85:             }
86: 
87:             if (component.DipVisionPos.IsEmpty)
88:             {
89:                 throw new Exception("未视角胶印模板！");
90:             }
91: 
92:             // 拍照位(相对于焊点)
93:             AKRSPoint3D visionPos =
94:                 bondPosition.CoordinateSystem.SelfPosToG0(new AKRSPoint3D()) + component.DipVisionPos;
95: 
96:             try
97:             {
98:                 // 去拍照位拍照
99:                 List<BaseAlgResult> baseAlgResults = this.system2Controller.BondCameraVisionDefect(
100:                     visionPos,
101:                     component.DipPRName, false, true);
102: 
103:                 // 蘸胶结果处理
104:                 ExcuteResult excuteResult = this.DipOnTUEpoxyCheck(component, baseAlgResults);
105: 
106:                 switch (excuteResult)
107:                 {
108:                     case ExcuteResult.Success:
109: 
110:                         // 去贴片位
111:                         bondPos.Z = component.IsActivateSlowTravelBeforeBonding
112:                                         ? (bondPos.Z + component.SlowTravelDistanceBeforeBonding)
113:                                         : bondPos.Z;
114: 
115:                         AKRSPoint3D bondPos3D = new AKRSPoint3D() { X = bondPos.X, Y = bondPos.Y, Z = bondPos.Z };
116: 
117:                         // 移动到贴片位
118:                         this.bondModuleController.MoveSafeBondXYZ(bondPos3D);
119: 
120:                         // 重新贴片
121:                         excuteResult = this.Bond(BondTypeEnum.BondOnTU);
122: 
123:                         return excuteResult;
124: 
125:                     case ExcuteResult.Fail:
126:                         bondPosition.SetMatterDisable();
127:                         return ExcuteResult.Success;
128: 
129:                     case ExcuteResult.Abort:
130:                         MachineStateModel.GetInstance().MachineState = MachineStateEnum.Stop;
131:                         return ExcuteResult.Abort;
132: 
133:                     default:
134:                         throw new Exception("胶量检测未知错误");
135:                 }
136:             }
137:             catch (Exception ex)
138:             {
139:                 LogHelper.Post(Level.Error, $"固晶流程：定位胶印失败", ex, LogCategory.Bond);
140: 
141:                 return ExcuteResult.Exception;
142:             }
143:         }

