219:         public ExcuteResult DipOnTUEpoxyCheck(BaseCarrierConfig component, List<BaseAlgResult> baseAlgResults)
220:         {
221:         Recheck:
222:             string alarmMessage = string.Empty;
223: 
224:             PREntity pREntity = (PREntity)VisionEntityRepository.GetInstance().Find(component.DipPRName);
225: 
226:             if (baseAlgResults == null)
227:             {
228:                 alarmMessage = this.Name + "：胶量检测未找到识别点";
229:             }
230:             else if (baseAlgResults.Count != (int)component.DipOnTUFluxNum)
231:             {
232:                 alarmMessage = this.Name + "：胶印检测识别到的个数不对";
233:             }
234:             else
235:             {
236:                 for (int i = 0; i < baseAlgResults.Count; i++)
237:                 {
238:                     BlobResult blobResult = (BlobResult)baseAlgResults[i];
239:                     MatchResult matchResult = new MatchResult(blobResult.CenterX, blobResult.CenterY, blobResult.Area);
240: 
241:                     // 定位结果和示教位置之间的差值
242:                     AKRSPoint3D pointResult = System2Module.GetInstance().BondModule.BondCameraCoordinateSystem
243:                         .ForwardConvertCoordinate(new AKRSPoint3D(matchResult.CenterX, matchResult.CenterY, 0));
244: 
245:                     double offsetX = pointResult.X - component.DipOnTUFluxCenterX[i] - component.FluxDistanceX;
246: 
247:                     double offsetY = pointResult.Y - component.DipOnTUFluxCenterY[i] - -component.FluxDistanceY;
248: 
249:                     //// 面积判断
250:                     //double limitArea = Math.Abs(blobResult.Area / component.DipOnTUFluxArea[i]);
251:                     //if (limitArea > component.TolerantFluxMax
252:                     //    || limitArea < component.TolerantFluxMin)
253:                     //{
254:                     //    alarmMessage +=
255:                     //        $"胶量检测点 {i + 1} 的面积的检测最大阈值为{component.TolerantFluxMax},"
256:                     //        + $"最小阈值为{component.TolerantFluxMin}\r\n,当前值为{limitArea}\r\n";
257:                     //    break;
258:                     //}
259: 
260:                     // X方向判断
261:                     if (Math.Abs(offsetX) > component.FluxLimitX)
262:                     {
263:                         alarmMessage =
264:                             $"胶量检测点 {i + 1} 的X方向的检测阈值为{component.FluxLimitX}\r\n,当前值为{offsetX}\r\n";
265:                         break;
266:                     }
267: 
268:                     // Y方向判断
269:                     if (Math.Abs(offsetY) > component.FluxLimitY)
270:                     {
271:                         alarmMessage +=
272:                             $"胶量检测点 {i + 1} 的Y方向的检测阈值为{component.FluxLimitY}\r\n,当前值为{offsetY}\r\n";
273:                         break;
274:                     }
275:                 }
276:             }
277: 
278:             if (alarmMessage != string.Empty)
279:             {
280:                 (DialogResult dialogResult, BaseAlgResult match) result = UcMainSystem.VisionAlarmFunc(
281:                     pREntity,
282:                     component.DipPRName + "胶印检测失败\r\n" + "原因：" + alarmMessage,
283:                     "胶印检测失败");
284: 
285:                 if (result.dialogResult == DialogResult.OK)
286:                 {
287:                     baseAlgResults = pREntity.AlgResults;
288:                     goto Recheck;
289:                 }
290:                 else if (result.dialogResult == DialogResult.Ignore)
291:                 {
292:                     return ExcuteResult.Fail;
293:                 }
294:                 else if (result.dialogResult == DialogResult.Abort)
295:                 {
296:                     return ExcuteResult.Abort;
297:                 }
298:                 else
299:                 {
300:                     throw new Exception("检测未知错误");
301:                 }
302:             }
303: 
304:             return ExcuteResult.Success;
