bond-position.code:
498:         private AKRSPoint4D CalculateBondPos()
499:         {
500:             #region 贴片角度计算
501: 
502:             // 当前焊点的角度
503:             double bpAngle = this.bondPosition.CoordinateSystem.DegreeInG0() * 180.0 / Math.PI;
504: 
505:             // 角度计算 = 当前角度 + 回正角度 + 下视定位结果 + 焊点的角度 + 贴片角度硬补偿
506:             double needRotaryAngle = this.bondHeadController.GetAxisTRealPos()
507:                                      + this.bondPosition.BondPositionInfo.ComponentAngleOffSet + bpAngle
508:                                      + this.bondPosition.GetRotaryCompensate();
509: 
510:             #endregion
511: 
512:             #region 焊点所在的位置计算
513: 
514:             // 焊点XY位置硬补偿
515:             AKRSPoint3D bondPosOffset = new AKRSPoint3D(this.bondPosition.GetPositionCompensate().X, this.bondPosition.GetPositionCompensate().Y, 0);
516: 
517:             // 焊点在G0中的位置（硬补偿随角度旋转） 
518:             AKRSPoint3D bondPosAddOffset = this.bondPosition.CoordinateSystem.SelfPosToG0(bondPosOffset);
519: 
520:             // 焊后补偿
521:             AKRSPoint3D defectCompensation = DefectCompensate.GetPostBondCompensation(this.bondPosition.Name);
522: 
523:             // 单科焊点的单独补偿
524:             AKRSPoint3D singleBpCompensation = DefectCompensate.GetBpSeparateOffset(this.bondPosition);
525:    
526:             // 真实贴片的位置为焊点的焊点的位置+焊点硬补偿 - 上视的偏移值 + 温漂补偿
527:             this.realBondPositionInG0 = bondPosAddOffset + defectCompensation + singleBpCompensation;
528: 
529:             #endregion
530: 
531:             #region 芯片位置计算
532: 
533:             AKRSPoint3D point3D = new AKRSPoint3D();
534: 
535:             // 判断纠偏相机类型
536:             if (component.AccuracyMode == AccuracyModeEnum.Off)
537:             {
538:                 // 盲贴模式下只能默认芯片和吸嘴重合
539:                 // 盲贴模式吸嘴还需要回到原来的位置
540:                 needRotaryAngle -= component.PickAngleOffset;
541: 
542:                 AKRSPoint2D nozzleOffsetRotated = this.bondHeadController.GetNozzleOffset(
543:                     nozzle.Name,
544:                     needRotaryAngle - nozzle.AlignAngle);
545: 
546:                 realBondPositionInG0.X -= nozzleOffsetRotated.X;
547: 
548:                 realBondPositionInG0.Y -= nozzleOffsetRotated.Y;
549:             }
550:             else if (component.AdjustCamera == CameraTypeEnum.BondCamera)
551:             {
552:                 // 中转台模式下芯片和吸嘴重合
553:                 AKRSPoint2D nozzleOffsetRotated = this.bondHeadController.GetNozzleOffset(
554:                     nozzle.Name,
555:                     needRotaryAngle - nozzle.AlignAngle);
556: 
557:                 realBondPositionInG0.X -= nozzleOffsetRotated.X;
558: 
559:                 realBondPositionInG0.Y -= nozzleOffsetRotated.Y;
560: 
561:                 point3D = RealTimeCorrection.GetInstance().GetCompensatePoint3D(
562:                 this.bondPosition.BondPositionInfo.IPTVisionPos,
563:                 this.bondPosition.BondPositionInfo.IPTPickPos,
564:                realBondPositionInG0 - BondDevicePara.GetInstance().BondHeadParam.HeadToCameraOffset,
565:                realBondPositionInG0);
566: 
567:                 this.bondPosition.BondPositionInfo.TpMarkCompensate = point3D;
568:             }
569:             else if (component.AdjustCamera == CameraTypeEnum.UpLookCamera)
570:             {
571:                 // 上视计算芯片和旋转中心的距离(旋转相对距离)
572:                 double angle = needRotaryAngle - this.bondHeadController.GetAxisTRealPos();
573: 
574:                 AKRSPoint3D upLookOff = MathHelper.RotateCenter(this.bondPosition.BondPositionInfo.ComponentOffSet, angle / 180.0 * Math.PI);
575:                 upLookOff = new AKRSPoint3D(upLookOff.X, upLookOff.Y, 0);
576:                 realBondPositionInG0 += upLookOff;
577:             }
578: 
579:             realBondPositionInG0 -= TransportUnitCompensate.GetInstance().GetBondCompensate(
580:                 this.realBondPositionInG0.X,
581:                 this.realBondPositionInG0.Y);
582: 
583:             if (this.component.IsConfirmReferencePoint)
584:             {
585:                 realBondPositionInG0 += this.component.IPTComponentReference;
586:             }
587: 
588:             this.bondPosition.BondPositionInfo.RealBondPoint3D = realBondPositionInG0;
589: 
590:             
591: 
592:             // 真实贴片位，换到轴坐标
593:             AKRSPoint3D realBondPosition = this.bondModuleController.ConvertG0ToMachinePos(realBondPositionInG0) + point3D;
594:             
595:             System2RunTimeProvider.RecordTime("BondAction", "真实贴片位转到轴坐标" + $" X：{realBondPosition.X}," + $" Y: {realBondPosition.Y}");
596: 
597:             #endregion
598: 
599:             #region 固精高度
600: 
601:             // 力控模式不用这个硬补偿
602:             double bondingDistance =
603:                 component.BondingForceMode == ForceModeEnum.Distance ? component.BondingDistance : 0;
604: 
605:             // 计算最终固晶高度=焊点示教高度+当前吸嘴测高补偿+芯片厚度+焊点贴片补偿
606:             this.bondLevel = this.bondModuleController.ConvertG0ToMachinePos(bondPosAddOffset).Z
607:                              + this.bondHeadController.GetCurrentNozzle().MeasureHeightOffset + component.ComponentThickness
608:                              + this.bondPosition.GetPositionCompensate().Z + bondingDistance;
609: 
610:             // 蘸胶安全高度
611:             double dipSafeLevel =
612:                 this.bondModuleController
613:                     .ConvertG0ToMachinePos(BondDevicePara.GetInstance().SlideFluxerParam.SlideFluxerRightBottomPos).Z
614:                 + this.bondHeadController.GetCurrentNozzle().MeasureHeightOffset + 3;
615: 
616:             // 计算抬起高度
617:             liftLevel = component.DipMode == DipModeEnum.AfterAccuracyMode
618:                             ? dipSafeLevel
619:                             : this.bondModuleController.GetBondheadSafeLevel();
620: 
621:             double offsetAngle = 0;
622: 
623:             #endregion
624: 
625:             // 固晶位置
626:             return new AKRSPoint4D()
627:                        {
628:                            X = realBondPosition.X, Y = realBondPosition.Y, Z = this.bondLevel, T = needRotaryAngle
629:                        };

